#!/bin/bash# scripts/generate_context_snapshot.sh# Генерирует CONTEXT_SNAPSHOT.md из текущего состояния репозиторияecho "# 📦 CONTEXT_SNAPSHOT.md — Temporal Semiotics Project" > CONTEXT_SNAPSHOT.mdecho "**Дата фиксации:** $(date -u +"%Y-%m-%dT%H:%M:%SZ")" >> CONTEXT_SNAPSHOT.mdecho "**Статус:** ✅ Все инварианты соблюдены, контур закрыт" >> CONTEXT_SNAPSHOT.mdecho "" >> CONTEXT_SNAPSHOT.md# Добавляем вывод ключевых проверокecho "## 🔹 Проверка валидации" >> CONTEXT_SNAPSHOT.mdpython -m pytest tests/test_validator.py -v --tb=no -q >> CONTEXT_SNAPSHOT.md 2>&1echo "" >> CONTEXT_SNAPSHOT.md# Добавляем статус Gitecho "## 🔹 Git статус" >> CONTEXT_SNAPSHOT.mdgit status --short >> CONTEXT_SNAPSHOT.mdecho "" >> CONTEXT_SNAPSHOT.md# Добавляем последние коммитыecho "## 🔹 Последние коммиты" >> CONTEXT_SNAPSHOT.mdgit log -3 --oneline >> CONTEXT_SNAPSHOT.mdecho "✅ CONTEXT_SNAPSHOT.md сгенерирован"